/// The description and unit of an option or hook.
pub fn option_text(name: &str) -> Option<(&'static str, &'static str)> {
    OPTION_TEXT.binary_search_by(|(n, _, _)| (*n).cmp(name)).ok().map(|i| (OPTION_TEXT[i].1, OPTION_TEXT[i].2))
}

